#!/bin/sh
system_menu(){ while :; do c=$(ui_menu System 'General system configuration.' hostname 'Set hostname' hosts 'Edit hosts file' dns 'Edit resolver configuration' locale 'Configure locale' timezone 'Configure timezone' users 'User and group tools' sudo 'Configure sudo/doas' terminal 'Configure terminal environment' env 'Edit environment' motd 'Configure MOTD') || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $c in hostname) h=$(ui_input Hostname 'New hostname:' "$(hostname)") || continue; printf '%s\n' "$h"|as_root tee /etc/hostname >/dev/null; have hostname && as_root hostname "$h" 2>/dev/null || true;; hosts) edit_file /etc/hosts;; dns) edit_file /etc/resolv.conf;; locale) locale_menu;; timezone) timezone_menu;; users) users_menu;; sudo) privilege_admin_menu;; terminal) t=$(ui_input TERM 'TERM value:' "${TERM:-xterm-256color}") || continue; replace_block "$CURRENT_HOME/.profile" terminal "export TERM=$t\nexport COLORTERM=truecolor";; env) edit_file /etc/environment;; motd) edit_file /etc/motd;; esac; done; }
locale_menu(){ l=$(ui_input Locale 'Locale:' en_US.UTF-8) || return; [ -e /etc/locale.gen ] && { grep -q "^$l" /etc/locale.gen || printf '%s UTF-8\n' "$l"|as_root tee -a /etc/locale.gen >/dev/null; have locale-gen && as_root locale-gen; }; replace_block "$CURRENT_HOME/.profile" locale "export LANG=$l\nexport LC_ALL=$l"; }
timezone_menu(){ z=$(ui_input Timezone 'Zoneinfo name:' America/New_York) || return; [ -e "/usr/share/zoneinfo/$z" ] && { as_root ln -sf "/usr/share/zoneinfo/$z" /etc/localtime; printf '%s\n' "$z"|as_root tee /etc/timezone >/dev/null; } || ui_msg Timezone 'Zoneinfo entry not found.'; }
users_menu(){ c=$(ui_menu Users 'Account management.' add 'Add user' password 'Change password' shell 'Change user shell' groups 'Show groups' groupadd 'Add group') || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $c in add) u=$(ui_input User 'Username:' '') || return; have adduser && as_root adduser "$u" || as_root useradd -m "$u";; password) u=$(ui_input Password 'Username:' "$CURRENT_USER") || return; as_root passwd "$u";; shell) u=$(ui_input User 'Username:' "$CURRENT_USER") || return; s=$(ui_input Shell 'Shell path:' /bin/bash) || return; as_root chsh -s "$s" "$u";; groups) ui_text Groups "$(id; getent group 2>/dev/null|head -n 100)";; groupadd) g=$(ui_input Group 'Name:' '') || return; as_root groupadd "$g";; esac; }
sudo_menu(){ c=$(ui_menu Privilege 'Configure administrative tools.' sudoers 'Edit sudoers safely' doas 'Edit doas.conf' install 'Install sudo/doas' add 'Add current user to admin group') || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $c in sudoers) have visudo && as_root visudo || edit_file /etc/sudoers;; doas) edit_file /etc/doas.conf;; install) p=$(ui_input Privilege 'Package:' sudo) || return; run_capture Install pkg_install "$p";; add) if getent group sudo >/dev/null 2>&1; then as_root usermod -aG sudo "$CURRENT_USER"; elif getent group wheel >/dev/null 2>&1; then as_root usermod -aG wheel "$CURRENT_USER"; fi;; esac; }
